def create_rules(apps, schema_editor):
    Rule = apps.get_model("chatbot", "LeadCategoryRule")
    User = apps.get_model("auth", "User")
    users = list(User.objects.filter(is_active=True))
    for category, names in DEFAULT_PEOPLE.items():
        rule, _ = Rule.objects.get_or_create(category=category)
        for name in names:
            match = [u for u in users if (u.first_name or "").strip().lower() == name
                     or (u.username or "").strip().lower().startswith(name)]
            if len(match) == 1:
                rule.sales_people.add(match[0])


